// Business presentation for the churn & retention project.
// All numbers come from deck_data.json, generated by `python -m src.slides`
// from reports/tables — nothing on the slides is typed by hand.
//
//   python -m src.slides        (writes deck_data.json, then runs this file)

const path = require("path");
const pptxgen = require("pptxgenjs");
const { applyTheme } = require("./apply_theme.js");
const D = require("./deck_data.json");

const OUT = path.join(__dirname, "..", "churn_retention_presentation.pptx");

// ---------------------------------------------------------------------------
// Theme: dark ink for structure, coral = risk / loss, teal = saved / gain.
// ---------------------------------------------------------------------------
const THEME = {
  name: "Retention Ink",
  headFontFace: "Cambria",
  bodyFontFace: "Calibri",
  colors: {
    dk1: "172A3A", lt1: "FFFFFF", dk2: "4A6072", lt2: "EEF2F5",
    accent1: "E4572E", accent2: "17A398", accent3: "F2A541",
    accent4: "8A9BA8", accent5: "C9D3DB", accent6: "2E4A62",
    hlink: "17A398", folHlink: "4A6072",
  },
};
const H = THEME.colors; // hex, for options that do not accept scheme colors

const pres = new pptxgen();
pres.layout = "LAYOUT_WIDE"; // 13.333 x 7.5 in
pres.theme = { headFontFace: THEME.headFontFace, bodyFontFace: THEME.bodyFontFace };
pres.title = "Customer churn & retention campaign";
pres.author = "Portfolio project";
const C = pres.SchemeColor;

// ---------------------------------------------------------------------------
// Formatting helpers
// ---------------------------------------------------------------------------
const pct = (x, d = 0) => `${(x * 100).toFixed(d)}%`;
const money = (x) => {
  const s = x < 0 ? "−" : "";
  const a = Math.abs(x);
  return a >= 1000 ? `${s}$${(a / 1000).toFixed(a >= 10000 ? 0 : 1)}k` : `${s}$${a.toFixed(0)}`;
};

// ---------------------------------------------------------------------------
// Layouts
// ---------------------------------------------------------------------------
const W = 13.333, M = 0.6;

pres.defineSlideMaster({
  title: "DARK",
  background: { color: C.text1 },
  objects: [
    { placeholder: { options: { name: "title", type: "title", x: M, y: 1.2, w: W - 2 * M, h: 1.6,
        fontFace: THEME.headFontFace, fontSize: 44, bold: true, color: C.background1, valign: "bottom", margin: 0 }, text: "" } },
    { placeholder: { options: { name: "body", type: "body", x: M, y: 2.95, w: W - 2 * M, h: 0.8,
        fontSize: 18, color: C.accent5, valign: "top", margin: 0 }, text: "" } },
  ],
});

pres.defineSlideMaster({
  title: "CONTENT",
  background: { color: C.background1 },
  margin: [0.5, M, 0.6, M],
  objects: [
    { placeholder: { options: { name: "title", type: "title", x: M, y: 0.35, w: W - 2 * M, h: 0.85,
        fontFace: THEME.headFontFace, fontSize: 34, bold: true, color: C.text1, valign: "middle", margin: 0 }, text: "" } },
    { text: { text: "Customer churn & retention · portfolio project",
        options: { x: M, y: 7.0, w: 6, h: 0.3, fontSize: 10, color: C.accent4, margin: 0 } } },
  ],
  slideNumber: { x: W - M - 0.6, y: 7.0, w: 0.6, h: 0.3, fontSize: 10, color: C.accent4, align: "right" },
});

// ---------------------------------------------------------------------------
// Reusable components (fresh option objects every call — pptxgenjs mutates them)
// ---------------------------------------------------------------------------
function card(slide, x, y, w, h, fill = C.background2, name = "card") {
  slide.addShape(pres.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.12,
    fill: { color: fill }, line: { color: fill, width: 0 }, objectName: name });
}

function stat(slide, x, y, w, value, label, color = C.accent1, labelColor = C.text2, valueSize = 44) {
  const vh = Math.max(0.85, (valueSize * 1.3) / 72); // value box grows with the font size
  slide.addText(value, { x, y, w, h: vh, fontFace: THEME.headFontFace, fontSize: valueSize, bold: true,
    color, margin: 0, valign: "bottom", isTextBox: true, objectName: `stat ${label.slice(0, 20)}` });
  slide.addText(label, { x, y: y + vh + 0.05, w, h: 0.75, fontSize: 14, color: labelColor, margin: 0,
    valign: "top", isTextBox: true });
}

function badge(slide, x, y, text, fill, size = 0.5) {
  slide.addShape(pres.ShapeType.ellipse, { x, y, w: size, h: size, fill: { color: fill }, line: { color: fill, width: 0 } });
  slide.addText(text, { x, y, w: size, h: size, fontSize: 16, bold: true, color: C.background1,
    align: "center", valign: "middle", margin: 0, isTextBox: true });
}

function chartStyle(extra = {}) {
  return Object.assign({
    catAxisLabelColor: H.dk2, valAxisLabelColor: H.dk2,
    catAxisLabelFontSize: 12, valAxisLabelFontSize: 12,
    catAxisLabelFontFace: "+mn-lt", valAxisLabelFontFace: "+mn-lt",
    catAxisLineShow: false, valAxisLineShow: false,
    valGridLine: { color: "DDE3E8", size: 0.5 }, catGridLine: { style: "none" },
    legendFontSize: 12, legendFontFace: "+mn-lt", legendColor: H.dk2,
    dataLabelFontSize: 11, dataLabelFontFace: "+mn-lt", dataLabelColor: H.dk1,
    titleFontFace: "+mn-lt", titleFontSize: 14, titleColor: H.dk1,
  }, extra);
}

function footnote(slide, text, y = 6.5) {
  slide.addText(text, { x: M, y, w: W - 2 * M, h: 0.42, fontSize: 11, italic: true,
    color: C.text2, margin: 0, isTextBox: true });
}

// ===========================================================================
// 1. Title
// ===========================================================================
pres.addSection({ title: "Overview" });
let s = pres.addSlide({ masterName: "DARK", sectionTitle: "Overview" });
s.addText("Keeping card customers from leaving", { placeholder: "title" });
s.addText("Churn prediction and a retention campaign sized by expected profit", { placeholder: "body" });
const exitY = 4.55;
stat(s, M, exitY, 3.6, pct(D.churn_rate), "of customers left the bank in the last year", C.accent1, C.accent5, 54);
stat(s, M + 4.1, exitY, 3.6, pct(D.model.recall_top_k), `of all leavers found by calling the riskiest ${D.top_k}%`, C.accent2, C.accent5, 54);
stat(s, M + 8.2, exitY, 3.9, money(D.decision.profit_per_10k), "expected campaign profit per 10k customers (assumption-based)", C.accent3, C.accent5, 54);
s.addNotes(
  `The bank lost ${pct(D.churn_rate, 1)} of ${D.n_customers.toLocaleString("en-US")} credit-card customers. ` +
  `We built a model that ranks customers by risk, sized a retention campaign by expected profit, and designed the A/B test that will confirm the effect. ` +
  `Money figures are illustrative: they rest on assumed customer value, contact cost and save rate.`);

// ===========================================================================
// 2. The problem
// ===========================================================================
pres.addSection({ title: "Problem" });
s = pres.addSlide({ masterName: "CONTENT", sectionTitle: "Problem" });
s.addText("Leavers hide in the low-activity segments", { placeholder: "title" });
const A = D.activity;
s.addChart(pres.ChartType.bar, [
  { name: "Share of customers", labels: A.labels, values: A.share_base },
  { name: "Share of leavers", labels: A.labels, values: A.share_churners },
], chartStyle({
  x: M, y: 1.45, w: 7.6, h: 5.0, barDir: "col", barGrouping: "clustered", barGapWidthPct: 60,
  chartColors: [H.accent5, H.accent1], showLegend: true, legendPos: "t",
  showValue: true, dataLabelPosition: "outEnd", dataLabelFormatCode: "0%", valAxisLabelFormatCode: "0%",
  valAxisHidden: true, valGridLine: { style: "none" },
  showTitle: true, title: "Activity segment (rule-based, SQL)",
}));
// Right column: the two lowest-activity segments combined
const lowIdx = [0, 1];
const lowBase = lowIdx.reduce((a, i) => a + A.share_base[i], 0);
const lowChurn = lowIdx.reduce((a, i) => a + A.share_churners[i], 0);
card(s, 8.6, 1.55, 4.13, 4.85);
stat(s, 8.9, 1.75, 3.6, pct(lowChurn), `of all leavers come from the ${A.labels[0].toLowerCase()} and ${A.labels[1].toLowerCase()} segments`, C.accent1);
stat(s, 8.9, 3.6, 3.6, pct(lowBase), "of customers sit in those two segments", C.text1);
s.addText(`Churn rate there: ${pct(A.churn_rate[0])} and ${pct(A.churn_rate[1])}, versus ${pct(A.churn_rate[A.churn_rate.length - 1])} among highly active customers.`,
  { x: 8.9, y: 5.4, w: 3.6, h: 0.9, fontSize: 14, color: C.text2, margin: 0, valign: "top", isTextBox: true });
s.addNotes("Segments are simple SQL rules on transaction count, inactivity and quarter-on-quarter change (sql/03_activity_segmentation.sql). Demographics (gender, income, education) move churn by only a few points, so the campaign targets behaviour, not demographics.");

// ===========================================================================
// 3. Signals (hypothesis tests)
// ===========================================================================
s = pres.addSlide({ masterName: "CONTENT", sectionTitle: "Problem" });
s.addText("Four of five suspected signals hold up", { placeholder: "title" });
const cw = 3.85, ch = 2.45, gx = 0.29, gy = 0.3, y0 = 1.45;
D.hypotheses.forEach((h, i) => {
  const col = i % 3, row = Math.floor(i / 3);
  const x = M + col * (cw + gx), y = y0 + row * (ch + gy);
  card(s, x, y, cw, ch, C.background2, `hypothesis ${i + 1}`);
  badge(s, x + 0.25, y + 0.25, h.actionable ? "✓" : "✗", h.actionable ? C.accent2 : C.accent4);
  s.addText(h.short_name, { x: x + 0.9, y: y + 0.22, w: cw - 1.1, h: 0.56, fontSize: 17, bold: true,
    color: C.text1, margin: 0, valign: "middle", isTextBox: true });
  s.addText(h.slide_stat, { x: x + 0.25, y: y + 0.9, w: cw - 0.5, h: 0.5, fontFace: THEME.headFontFace,
    fontSize: 24, bold: true, color: h.actionable ? C.accent1 : C.accent4, margin: 0, isTextBox: true });
  s.addText(h.slide_text, { x: x + 0.25, y: y + 1.42, w: cw - 0.5, h: ch - 1.55, fontSize: 14,
    color: C.text2, margin: 0, valign: "top", isTextBox: true });
});
// 6th cell: takeaway
{
  const x = M + 2 * (cw + gx), y = y0 + (ch + gy);
  card(s, x, y, cw, ch, C.text1, "takeaway");
  s.addText([
    { text: "Takeaway", options: { bold: true, fontSize: 17, color: C.background1, breakLine: true } },
    { text: "Behaviour predicts churn, demographics don't. Watch usage, products and balance, not age.", options: { fontSize: 15, color: C.accent5 } },
  ], { x: x + 0.3, y: y + 0.25, w: cw - 0.6, h: ch - 0.5, margin: 0, valign: "top", paraSpaceAfter: 6, isTextBox: true });
}
s.addNotes("Each signal was tested with the appropriate statistical test (chi-square, Mann-Whitney, Welch t-test), with Holm correction for testing five at once. A signal counts only if it is significant AND the effect is not negligible. These are associations, not proof of cause.");

// ===========================================================================
// 4. The model
// ===========================================================================
pres.addSection({ title: "Solution" });
s = pres.addSlide({ masterName: "CONTENT", sectionTitle: "Solution" });
const lift = D.model.recall_top_k / D.model.rules_recall_top_k;
s.addText(`A risk score finds ${lift.toFixed(1)}× more leavers than rules`, { placeholder: "title" });
const G = D.gains;
const gl = G.shares.map((v) => pct(v));
s.addChart(pres.ChartType.line, [
  { name: "Model risk score", labels: gl, values: G.model },
  { name: "Simple SQL rules", labels: gl, values: G.rules },
  { name: "Random calling", labels: gl, values: G.random },
], chartStyle({
  x: M, y: 1.45, w: 7.6, h: 5.0, chartColors: [H.accent2, H.accent3, H.accent4],
  lineSize: 2.5, lineDataSymbol: "none", showLegend: true, legendPos: "b",
  valAxisLabelFormatCode: "0%", valAxisMaxVal: 1, valAxisMinVal: 0,
  catAxisLabelFrequency: 4,
  showTitle: true, title: "Share of leavers reached vs share of customers called",
}));
card(s, 8.6, 1.55, 4.13, 4.85);
stat(s, 8.9, 1.75, 3.6, pct(D.model.recall_top_k), `of leavers reached by calling the top ${D.top_k}% (rules: ${pct(D.model.rules_recall_top_k)}, random: ${D.top_k}%)`, C.accent2);
stat(s, 8.9, 3.6, 3.6, pct(D.model.precision_top_k, 1), `of the customers called would really have left`, C.text1);
const drivers = { total_trans_ct: "number of transactions", total_trans_amt: "yearly spend", total_revolving_bal: "revolving balance",
  total_ct_chng_q4_q1: "recent drop in usage", total_relationship_count: "number of products", total_amt_chng_q4_q1: "recent drop in spend",
  avg_trans_amt: "average purchase size", trans_ct_per_product: "usage per product", months_inactive_12_mon: "inactive months",
  contacts_count_12_mon: "contacts with the bank", avg_utilization_ratio: "credit utilisation", customer_age: "age" };
const top3 = D.shap_top.slice(0, 3).map((d) => drivers[d.feature] || d.feature);
s.addText(`Top signals: ${top3.join(", ")}.`, { x: 8.9, y: 5.45, w: 3.6, h: 0.85, fontSize: 14, color: C.text2, margin: 0, valign: "top", isTextBox: true });
footnote(s, `Measured on ${D.n_test.toLocaleString("en-US")} customers held out from training. Technical: ROC-AUC ${D.model.roc_auc.toFixed(3)}, PR-AUC ${D.model.pr_auc.toFixed(3)}.`);
s.addNotes("CatBoost gradient boosting, calibrated so that a score of 30% means about 30% of such customers leave. The test set was never used for training or tuning. On real bank data, with features computed strictly before the prediction date, expect lower accuracy than on this clean public dataset.");

// ===========================================================================
// 5. Profit curve
// ===========================================================================
pres.addSection({ title: "Money" });
s = pres.addSlide({ masterName: "CONTENT", sectionTitle: "Money" });
s.addText(`Call the right ${pct(D.decision.share_contacted)}, not everyone`, { placeholder: "title" });
const P = D.profit_curve;
s.addChart(pres.ChartType.line, [
  { name: "Campaign profit per 10k customers", labels: P.shares.map((v) => pct(v)), values: P.profit_per_10k.map((v) => Math.round(v)) },
], chartStyle({
  x: M, y: 1.45, w: 7.6, h: 5.0, chartColors: [H.accent2], lineSize: 3, lineDataSymbol: "none",
  showLegend: false, valAxisLabelFormatCode: "$#,##0", catAxisLabelFrequency: 4,
  showTitle: true, title: "Profit per 10k customers vs share of customers called",
}));
card(s, 8.6, 1.55, 4.13, 4.85);
stat(s, 8.9, 1.75, 3.6, money(D.decision.profit_per_10k), `profit per 10k customers when calling ${pct(D.decision.share_contacted)} of them (${pct(D.decision.churners_reached_share)} of leavers)`, C.accent2);
stat(s, 8.9, 3.6, 3.6, money(D.decision.everyone_profit_per_10k), "if we called every customer: most would have stayed anyway", C.accent1);
s.addText("Rule: call a customer only if risk × value saved exceeds the $35 cost of the call and offer.",
  { x: 8.9, y: 5.45, w: 3.6, h: 0.85, fontSize: 14, color: C.text2, margin: 0, valign: "top", isTextBox: true });
footnote(s, "Illustrative: assumes customer value ≈ 2 years of card income, $15 call + $40 offer (half accept), 25% of called leavers saved.");
s.addNotes("The curve rises while we call people who would leave, peaks, then falls as we spend on people who would stay anyway. The campaign size was chosen without looking at the test data (rule: expected profit > 0).");

// ===========================================================================
// 6. Sensitivity
// ===========================================================================
s = pres.addSlide({ masterName: "CONTENT", sectionTitle: "Money" });
const R = D.robust;
s.addText(`Profitable as long as ${pct(R.break_even_success)}+ of leavers are saved`, { placeholder: "title" });
const S = D.sensitivity;
const slabels = S.labels.map((l) => l.replace(" (value of a customer)", "").replace(/_/g, " "));
s.addChart(pres.ChartType.bar, [
  { name: "Assumption 50% lower", labels: slabels, values: S.low.map((v) => Math.round(v)) },
  { name: "Assumption 50% higher", labels: slabels, values: S.high.map((v) => Math.round(v)) },
], chartStyle({
  x: M, y: 1.45, w: 7.6, h: 5.0, barDir: "bar", barGrouping: "clustered", barGapWidthPct: 50,
  chartColors: [H.accent1, H.accent2], showLegend: true, legendPos: "b",
  showValue: true, dataLabelPosition: "outEnd", dataLabelFormatCode: "$#,##0",
  valAxisLabelFormatCode: "$#,##0", valAxisHidden: true, valGridLine: { style: "none" },
  showTitle: true, title: `Best achievable profit per 10k customers (base case ${money(S.base)})`,
}));
card(s, 8.6, 1.55, 4.13, 4.85);
stat(s, 8.9, 1.75, 3.6, pct(R.break_even_success), `save rate where the campaign breaks even; we assume ${pct(R.assumed_success)}, the biggest unknown`, C.accent1);
stat(s, 8.9, 3.6, 3.6, `${pct(R.band_low)}–${pct(R.band_high)}`, "of customers called: any size in this band earns within 5% of the best profit", C.accent2, C.text2, 40);
s.addText("Save rate and customer value matter most; call and offer costs matter much less.",
  { x: 8.9, y: 5.45, w: 3.6, h: 0.85, fontSize: 14, color: C.text2, margin: 0, valign: "top", isTextBox: true });
s.addNotes("Each assumption was moved 50% down and up while the others stayed fixed, and the campaign was re-optimised. Save rate and customer value move profit identically because benefit = risk x save rate x value. The best campaign size jumps between scenarios because the profit curve is flat near its peak, so choosing any size in the flat band costs little.");

// ===========================================================================
// 7. A/B test plan
// ===========================================================================
pres.addSection({ title: "Plan" });
s = pres.addSlide({ masterName: "CONTENT", sectionTitle: "Plan" });
s.addText("Prove it with a controlled pilot before scaling", { placeholder: "title" });
const steps = [
  ["Split at random", `Targeted customers go 50/50 into a called group and an untouched control group`],
  ["Call one group", "Only the treatment group gets the call and offer; the control group gets nothing"],
  ["Measure 90-day churn", "Compare churn between the two groups, plus cost per saved customer"],
  ["Decide once", "Read the result at the planned end, not on the daily dashboard"],
];
const sw = 2.85, sg = 0.27;
steps.forEach(([t, d], i) => {
  const x = M + i * (sw + sg);
  card(s, x, 1.45, sw, 2.55, C.background2, `step ${i + 1}`);
  badge(s, x + 0.25, 1.65, String(i + 1), C.accent6);
  s.addText(t, { x: x + 0.25, y: 2.3, w: sw - 0.5, h: 0.45, fontSize: 16, bold: true, color: C.text1, margin: 0, valign: "middle", isTextBox: true });
  s.addText(d, { x: x + 0.25, y: 2.8, w: sw - 0.5, h: 1.1, fontSize: 14, color: C.text2, margin: 0, valign: "top", isTextBox: true });
});
const AB = D.ab;
stat(s, M, 4.3, 3.8, AB.n_per_arm.toLocaleString("en-US"), "customers per group needed (95% confidence, 80% power)", C.accent6);
stat(s, M + 4.2, 4.3, 3.8, pct(AB.mde), `smallest churn reduction worth detecting (from ${pct(AB.p_control)} baseline)`, C.accent2);
stat(s, M + 8.4, 4.3, 3.9, `${pct(AB.fpr_fixed)} → ${pct(AB.fpr_peeking)}`, "false 'wins' if the team stops the test the first time it looks good", C.accent1);
footnote(s, "Design plus simulation: the dataset has no experiment, so test outcomes were simulated from assumed effects. Only the baseline churn comes from the model.", 6.3);
s.addNotes(`Peeking problem: under no real effect, checking the result 20 times and stopping at the first 'significant' reading gave false wins in ${pct(AB.fpr_peeking)} of simulated tests instead of 5%. A pre-registered sample size, or a sequential design with stricter per-look thresholds (simulated: ${pct(AB.fpr_pocock)}), fixes this.`);

// ===========================================================================
// 8. Recommendations
// ===========================================================================
s = pres.addSlide({ masterName: "DARK", sectionTitle: "Plan" });
s.addText("Recommendations", { x: M, y: 0.45, w: W - 2 * M, h: 0.9, fontFace: THEME.headFontFace, fontSize: 40, bold: true,
  color: C.background1, margin: 0, isTextBox: true });
const nbaText = Object.entries(D.nba_secondary).filter(([, v]) => v > 5).map(([k, v]) => `${k} (${v})`).join(", ");
const recs = [
  ["Run the pilot", `Test the campaign on the top-risk segment with ${AB.n_per_arm.toLocaleString("en-US")} customers per group before any roll-out.`],
  ["Target by expected profit", `Call about ${pct(D.decision.share_contacted)} of customers, those whose risk × value covers the cost, not a fixed score cut-off.`],
  ["Personalise the offer", `Reactivate low usage first, then add an offer for the second risk signal: ${nbaText}.`],
  ["Replace the assumptions", "Plug in real customer P&L and the measured save rate, then move to uplift modelling to call only persuadable customers."],
];
recs.forEach(([t, d], i) => {
  const col = i % 2, row = Math.floor(i / 2);
  const x = M + col * 6.2, y = 1.65 + row * 2.45;
  card(s, x, y, 5.9, 2.15, C.accent6, `recommendation ${i + 1}`);
  badge(s, x + 0.3, y + 0.3, String(i + 1), C.accent2, 0.55);
  s.addText(t, { x: x + 1.05, y: y + 0.3, w: 4.6, h: 0.55, fontSize: 19, bold: true, color: C.background1, margin: 0, valign: "middle", isTextBox: true });
  s.addText(d, { x: x + 1.05, y: y + 0.95, w: 4.6, h: 1.1, fontSize: 15, color: C.accent5, margin: 0, valign: "top", isTextBox: true });
});
s.addNotes("Numbers in brackets are customers in the hold-out campaign list who get each secondary offer. Low or falling card usage is the main risk signal for almost every targeted customer, so every one of them gets a reactivation offer; the second offer is where personalisation happens. Each offer type should become an arm of the pilot test.");

// ---------------------------------------------------------------------------
(async () => {
  await pres.writeFile({ fileName: OUT });
  await applyTheme(OUT, THEME);
  console.log("wrote", OUT);
})();
